sect1.para:
  आधारभूत assignment operator का साथै binary arithmetic, array union र string operators का लागि "combined operators" पनि उपलब्ध छन्, जसले variable को हालको मान प्रयोग गरेर गणना गर्छ र नतिजालाई त्यही variable मा पुनः सेट गर्छ:

   Combined Assignments


<?php
$a = 3;
$a += 5; // $a मा ८ सेट हुन्छ; अर्थात् $a = $a + 5; जस्तै
$b = "Hello ";
$b .= "There!"; // $b मा "Hello There!" सेट हुन्छ; अर्थात् $b = $b . "There!";

var_dump($a, $b);
?>
